CREATE TYPE "user_role" AS ENUM (
  'student',
  'staff',
  'admin'
);

CREATE TYPE "review_status" AS ENUM (
  'visible',
  'hidden'
);

CREATE TABLE "users" (
  "user_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "student_id" varchar(20) UNIQUE,
  "email" varchar(255) UNIQUE NOT NULL,
  "first_name" varchar(100) NOT NULL,
  "last_name" varchar(100) NOT NULL,
  "display_name" varchar(100) NOT NULL,
  "role" user_role NOT NULL DEFAULT 'student',
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL
);

CREATE TABLE "users_invitations" (
  "user_invite_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "email" varchar(255) UNIQUE NOT NULL,
  "role" user_role NOT NULL DEFAULT 'staff'
);

CREATE TABLE "courses" (
  "course_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "course_code" varchar(20) UNIQUE NOT NULL,
  "name_th" varchar(255) NOT NULL,
  "name_en" varchar(255) NOT NULL,
  "credits" int NOT NULL,
  "description_th" text,
  "description_en" text,
  "prerequisite_note" text, -- เงื่อนไขเพิ่มเติมที่ไม่ใช่รายวิชาในระบบ (เช่น ผ่าน 60 หน่วยกิต, ขึ้นกับอาจารย์ผู้สอน)
  "is_active" boolean NOT NULL DEFAULT true,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL
);

CREATE TABLE "curriculum_versions" (
  "curriculum_version_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "version_name" varchar(100) NOT NULL,
  "academic_year" int UNIQUE NOT NULL,
  "total_credits" int NOT NULL,
  "is_active" boolean NOT NULL DEFAULT true,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL
);

CREATE TABLE "categories" (
  "category_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" varchar(50) UNIQUE NOT NULL,
  "category_name_th" varchar(100) NOT NULL,
  "category_name_en" varchar(100) NOT NULL,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL
);

CREATE TABLE "curriculum_categories" (
  "curriculum_category_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "curriculum_version_id" int NOT NULL,
  "category_id" int NOT NULL,
  "parent_curriculum_category_id" int,
  "required_credits" int NOT NULL,
  "sort_order" int NOT NULL DEFAULT 0,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL
);

CREATE TABLE "curriculum_category_courses" (
  "curriculum_category_id" int NOT NULL,
  "course_id" int NOT NULL,
  "is_required" boolean NOT NULL DEFAULT false,
  "standard_year" int,
  "standard_semester" int,
  PRIMARY KEY ("curriculum_category_id", "course_id")
);

-- กลุ่มของ track สำหรับจัดหน้า Track list (หลักสูตรไม่ได้กำหนด ทีมจัดเองตามวิชาที่แชร์กัน)
CREATE TABLE "track_groups" (
  "track_group_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "group_name_th" varchar(100) NOT NULL,
  "group_name_en" varchar(100) NOT NULL,
  "sort_order" int NOT NULL DEFAULT 0,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL
);

CREATE TABLE "tracks" (
  "track_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "curriculum_version_id" int NOT NULL,
  "track_group_id" int NOT NULL,
  "track_name_th" varchar(100) NOT NULL,
  "track_name_en" varchar(100) NOT NULL,
  "description_th" text,
  "description_en" text,
  "required_credits" int NOT NULL,
  "sort_order" int NOT NULL DEFAULT 0,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL
);

-- track ใกล้เคียง (กำหนดเอง ทางเดียว: track_id → related_track_id)
CREATE TABLE "related_tracks" (
  "track_id" int NOT NULL,
  "related_track_id" int NOT NULL,
  "sort_order" int NOT NULL DEFAULT 0,
  PRIMARY KEY ("track_id", "related_track_id"),
  CHECK ("track_id" <> "related_track_id")
);

CREATE TABLE "track_courses" (
  "track_id" int NOT NULL,
  "course_id" int NOT NULL,
  "is_required" boolean NOT NULL DEFAULT false,
  "choice_group" int, -- วิชาที่ choice_group เดียวกันใน track เดียวกัน = ต้องเลือกเรียน 1 วิชา
  "standard_year" int,
  "standard_semester" int,
  PRIMARY KEY ("track_id", "course_id")
);

CREATE TABLE "tags" (
  "tag_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "tag_name" varchar(50) UNIQUE NOT NULL,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL
);

CREATE TABLE "course_tags" (
  "course_id" int NOT NULL,
  "tag_id" int NOT NULL,
  PRIMARY KEY ("course_id", "tag_id")
);

CREATE TABLE "study_plans" (
  "study_plan_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" int NOT NULL,
  "curriculum_version_id" int NOT NULL,
  "track_id" int,
  "plan_name" varchar(100) NOT NULL,
  "is_default" boolean NOT NULL DEFAULT false,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL
);

-- วิชาที่นักศึกษาวางแผนเอง (ผลการเรียนอยู่ที่ student_course_grades, สิ่งที่ลงจริงอยู่ที่ registrar_enrollments)
-- วิชาเดียวกันวางแผนได้หลายเทอม (เช่น ติด F แล้ววางแผนลงซ้ำ) แต่ไม่ซ้ำในเทอมเดียวกัน
CREATE TABLE "study_plan_courses" (
  "study_plan_course_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "study_plan_id" int NOT NULL,
  "course_id" int NOT NULL,
  "study_year" int NOT NULL,
  "study_semester" int NOT NULL,
  CHECK ("study_semester" IN (1, 2))
);

CREATE TABLE "reviews" (
  "review_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" int NOT NULL,
  "course_id" int NOT NULL,
  "overall_rating" int NOT NULL,
  "difficulty_rating" int NOT NULL,
  "workload_rating" int NOT NULL,
  "comment" text,
  "status" review_status NOT NULL DEFAULT 'visible',
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL
);

-- วิชาบังคับก่อน
-- group_no เดียวกัน = เลือกผ่านอย่างใดอย่างหนึ่ง (OR), ต่าง group = ต้องผ่านทุก group (AND)
-- is_corequisite = true หมายถึง "ผ่านหรือเรียนพร้อมกันได้"
CREATE TABLE "course_prerequisites" (
  "course_prerequisite_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "course_id" int NOT NULL,
  "prerequisite_course_id" int NOT NULL,
  "group_no" int NOT NULL DEFAULT 1,
  "is_corequisite" boolean NOT NULL DEFAULT false,
  CHECK ("course_id" <> "prerequisite_course_id")
);

-- ===== Mock ระบบทะเบียน (แทนการเชื่อมระบบทะเบียนจริงของมหาวิทยาลัย) =====
-- ไม่ผูก FK กับ users: แถวใน users ถูกสร้างตอน login ครั้งแรก, จับคู่กันด้วย users.student_id
CREATE TABLE "registrar_students" (
  "student_id" varchar(20) PRIMARY KEY,
  "first_name_th" varchar(100) NOT NULL,
  "last_name_th" varchar(100) NOT NULL,
  "admission_year" int NOT NULL,          -- ปีการศึกษาที่เข้า เช่น 2567
  "curriculum_version_id" int NOT NULL,
  "current_year" int NOT NULL,            -- ชั้นปีปัจจุบัน
  "current_semester" int NOT NULL,        -- ภาคการศึกษาปัจจุบัน (1, 2)
  CHECK ("current_semester" IN (1, 2))
);

-- วิชาที่ลงทะเบียนจริง (ปี/เทอมเป็นปีการศึกษาจริง เช่น 2568/2)
-- แปลงเป็นชั้นปีของ planner: study_year = academic_year - admission_year + 1
CREATE TABLE "registrar_enrollments" (
  "enrollment_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "student_id" varchar(20) NOT NULL,
  "course_id" int NOT NULL,
  "academic_year" int NOT NULL,
  "semester" int NOT NULL,
  "status" varchar(20) NOT NULL DEFAULT 'registered',
  CHECK ("semester" IN (1, 2)),
  CHECK ("status" IN ('registered', 'withdrawn'))
);

-- เกรดที่นักศึกษากรอกเอง (ผูกกับวิชาที่ลงทะเบียนจริงเท่านั้น)
CREATE TABLE "student_course_grades" (
  "grade_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" int NOT NULL,
  "enrollment_id" int UNIQUE NOT NULL,
  "grade" varchar(2) NOT NULL,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL,
  CHECK ("grade" IN ('A', 'B+', 'B', 'C+', 'C', 'D+', 'D', 'F', 'S', 'U'))
);

CREATE UNIQUE INDEX ON "curriculum_categories" ("curriculum_version_id", "category_id");

CREATE UNIQUE INDEX ON "tracks" ("curriculum_version_id", "track_name_en");

CREATE UNIQUE INDEX ON "reviews" ("user_id", "course_id");

CREATE UNIQUE INDEX ON "study_plan_courses" ("study_plan_id", "course_id", "study_year", "study_semester");

-- 1 user มีได้หลายแผน (BE จำกัดไม่เกิน 5) แต่แผนหลัก (is_default) ได้แผนเดียว
CREATE UNIQUE INDEX ON "study_plans" ("user_id") WHERE "is_default";

CREATE UNIQUE INDEX ON "course_prerequisites" ("course_id", "prerequisite_course_id");

CREATE UNIQUE INDEX ON "registrar_enrollments" ("student_id", "course_id", "academic_year", "semester");

CREATE INDEX ON "registrar_enrollments" ("course_id");

ALTER TABLE "curriculum_categories" ADD FOREIGN KEY ("curriculum_version_id") REFERENCES "curriculum_versions" ("curriculum_version_id") DEFERRABLE INITIALLY IMMEDIATE;

